/* Public catalogue adapters. Personal entries remain in the account workspace. */
let liveExercises=[],exerciseLoad=null,exerciseStatus='Loading catalogues…',exerciseTimer,exerciseRequest=0;
const liveFetch=async(url)=>{const r=await fetch(url,{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('Source unavailable ('+r.status+')');return r.json()};
function safeMedia(url){try{let u=new URL(url);return u.protocol==='https:'?u.href:''}catch{return ''}}
function muscleGroup(s){s=s.toLowerCase();return /chest|pectoral/.test(s)?'Chest':/back|lat|trap/.test(s)?'Back':/abdom|abs|waist|core/.test(s)?'Core':/shoulder|deltoid/.test(s)?'Shoulders':/bicep|tricep|arms|forearm/.test(s)?'Arms':'Legs'}
function equipGroup(s){s=s.toLowerCase();return /dumbbell/.test(s)?'Dumbbell':/barbell|ez bar/.test(s)?'Barbell':/cable/.test(s)?'Cable':/body|none/.test(s)?'Bodyweight':s==='machine'?'Machine':s.replace(/^./,x=>x.toUpperCase())}
function normalizeEDB(e){return {id:'edb-'+e.exerciseId,name:e.name,source:'ExerciseDB',muscle:muscleGroup((e.bodyParts||[]).join(' ')),equipment:equipGroup((e.equipments||[]).join(', ')),type:(e.targetMuscles||[]).join(', '),instructions:e.instructions||[],images:[e.gifUrl].filter(Boolean),credit:'ExerciseDB / AscendAPI',sourceUrl:'https://oss.exercisedb.dev/docs'}}
async function loadLiveExercises(){if(exerciseLoad)return exerciseLoad;exerciseLoad=(async()=>{const results=await Promise.allSettled([liveFetch('data/free-exercises.json'),liveFetch('data/wger-exercises.json')]);let labels=[];results.forEach((r,i)=>{if(r.status==='fulfilled'){liveExercises.push(...r.value);labels.push((i?'wger':'Free Exercise DB')+' ready')}else labels.push((i?'wger':'Free Exercise DB')+' unavailable')});exerciseStatus=labels.join(' · ');if($('#catalog-results'))renderCatalogResults()})();return exerciseLoad}
const originalPicker=openExercisePicker;
openExercisePicker=function(){originalPicker();$('#modal-content .tag')?.remove();loadLiveExercises();searchExerciseDB()};
async function searchExerciseDB(){clearTimeout(exerciseTimer);const seq=++exerciseRequest;exerciseTimer=setTimeout(async()=>{let q=pickerState.q.trim();try{let url='https://oss.exercisedb.dev/api/v1/exercises'+(q?'/search?q='+encodeURIComponent(q)+'&limit=100':'?limit=100');let d=await liveFetch(url);if(seq!==exerciseRequest)return;liveExercises=liveExercises.filter(x=>x.source!=='ExerciseDB');liveExercises.push(...(d.data||[]).map(normalizeEDB));exerciseStatus='ExerciseDB ready · Free Exercise DB · wger'}catch{if(seq!==exerciseRequest)return;exerciseStatus='ExerciseDB unavailable · Other catalogues available'}if($('#catalog-results'))drawExerciseResults()},650)}
catalogMatches=function(){let words=pickerState.q.toLowerCase().trim().split(/\s+/).filter(Boolean);return liveExercises.filter(e=>words.every(w=>[e.name,e.muscle,e.equipment,e.type].join(' ').toLowerCase().includes(w))&&(!pickerState.muscle||e.muscle===pickerState.muscle)&&(!pickerState.equipment||e.equipment===pickerState.equipment)&&(!pickerState.source||e.source===pickerState.source)).sort((a,b)=>catalogProviders.indexOf(a.source)-catalogProviders.indexOf(b.source)||a.name.localeCompare(b.name))};
renderCatalogResults=function(){drawExerciseResults();searchExerciseDB()};
let exerciseVisible=60;
function drawExerciseResults(){let entries=catalogMatches(),node=$('#catalog-results');if(!node)return;$('#catalog-count').textContent=entries.length+' results · '+exerciseStatus;node.innerHTML=entries.slice(0,exerciseVisible).map(e=>`<button class="catalog-result" onclick="catalogDetail('${esc(e.id)}')"><div class="catalog-thumb">${e.images?.[0]?`<img loading="lazy" src="${esc(safeMedia(e.images[0]))}" alt="" onerror="this.hidden=true">`:equipmentIllustration(e)}</div><div class="catalog-result-info"><strong>${esc(e.name)}</strong><small>${esc(e.muscle)} · ${esc(e.equipment)}</small><span class="source-label">${esc(e.source)}</span></div><span>›</span></button>`).join('')+(entries.length>exerciseVisible?'<button class="text-btn full" onclick="exerciseVisible+=60;drawExerciseResults()">Show more exercises</button>':'')+(!entries.length?'<div class="empty">No matching exercises. Try another name or create a custom exercise.</div>':'')}
catalogDetail=function(id){let e=liveExercises.find(e=>e.id===id);if(!e)return;catalogSelection=e;let media=(e.images||[]).map(url=>`<img class="exercise-photo" src="${esc(safeMedia(url))}" alt="${esc(e.name)} demonstration" onerror="this.replaceWith(document.createTextNode('Image unavailable'))">`).join('');modal(`<button class="text-btn" onclick="openExercisePicker()">← Search results</button>`+modalHead(esc(e.name))+`<span class="source-label">${esc(e.source)}</span><div class="exercise-gallery">${media||'<p>Media unavailable for this exercise.</p>'}</div><div class="catalog-meta"><span>${esc(e.muscle)}</span><span>${esc(e.equipment)}</span></div><div class="catalog-guidance"><h3>Instructions</h3>${e.instructions?.length?'<ol>'+e.instructions.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol>':'<p>No instructions supplied by this source.</p>'}</div><p class="small-muted">${esc(e.credit||e.source)}${e.license?' · '+esc(e.license):''}${(e.mediaCredits||[]).length?' · Image credits: '+e.mediaCredits.map(c=>esc(c.author||'wger contributors')+' (licence '+esc(String(c.license))+')').join('; '):''} · <a href="${esc(safeMedia(e.sourceUrl))}" target="_blank" rel="noopener">Source & licence</a></p><form onsubmit="addCatalogExercise(event)"><div class="form-grid"><div><label>Sets</label><input id="catalog-sets" type="number" required min="1" max="20" value="3"></div><div><label>Reps</label><input id="catalog-reps" type="number" required min="1" max="100" value="10"></div><div><label>Weight (kg)</label><input id="catalog-weight" type="number" required min="0" max="2000" step=".5" value="0"></div><div><label>Rest (m:ss)</label><input id="catalog-rest" required pattern="[0-9]{1,2}:[0-5][0-9]" value="1:30"></div></div><button class="btn full">Add to ${exercisePickerTarget==='routine'?'routine':'workout'}</button></form>`);$('#modal').classList.add('catalog-modal')};
// Food results retain the source's per-100g values; absent nutrients are never inferred.
let remoteFoods=[],foodRemoteQuery='',foodRemoteStatus='',foodRequest=0,foodSearchCache=new Map(),lastFoodSearch=0;
function normalizeOFF(p){let n=p.nutriments||{},read=k=>n[k]===undefined||n[k]===null||n[k]===''?undefined:Number.isFinite(Number(n[k]))?Number(n[k]):undefined;let result={id:'off-'+p.code,barcode:p.code,name:p.product_name||p.product_name_en||'Unnamed product',brand:p.brands||'',basis:100,unit:'g',cal:read('energy-kcal_100g')??(read('energy_100g')===undefined?undefined:read('energy_100g')/4.184),p:read('proteins_100g'),c:read('carbohydrates_100g'),f:read('fat_100g'),sugar:read('sugars_100g'),saturates:read('saturated-fat_100g'),fiber:read('fiber_100g'),salt:read('salt_100g'),source:'Open Food Facts',sourceUrl:'https://world.openfoodfacts.org/product/'+p.code};result.incomplete=!['cal','p','c','f'].every(k=>Number.isFinite(result[k])&&result[k]>=0);return result}
foodLibrary=function(){state.products=state.products||[];state.foodFavorites=state.foodFavorites||[];return state.products};
const localFoodResults=foodResults;
foodResults=function(){let entries=localFoodResults();if(foodPicker.q.trim()===foodRemoteQuery&&!['favorites','own'].includes(foodPicker.tab)){let ids=new Set(entries.map(x=>x.id));entries.push(...remoteFoods.filter(x=>!ids.has(x.id)))}return entries};
const originalFoodPicker=renderFoodPicker;
renderFoodPicker=function(){originalFoodPicker();let row=$('#modal-content .food-search-row');if(row){let b=document.createElement('button');b.className='btn soft small';b.textContent='Search';b.onclick=searchOnlineFood;row.insertBefore(b,row.children[1]);$('#food-query').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();searchOnlineFood()}}}paintFoodResults()};
renderFoodResults=function(){paintFoodResults()};
function paintFoodResults(){let node=$('#food-results');if(!node)return;displayedFoods=foodResults();node.innerHTML=`<div class="catalog-result-heading"><span>${foodPicker.q?'Search results':foodPicker.tab==='recent'?'Recent '+esc(foodPicker.meal):esc(foodPicker.tab)}</span><span>${displayedFoods.length} foods</span></div><p class="small-muted" role="status">${esc(foodRemoteStatus)}</p><div class="catalog-results">${displayedFoods.map((p,i)=>`<div class="food-result"><button class="food-result-main" onclick="selectLiveFood(${i})"><span class="food-icon">🍽️</span><span><strong>${esc(p.name)}</strong><small>${esc(p.brand||'')}${p.brand?' · ':''}${p.incomplete?'Nutrition incomplete':round(p.cal)+' kcal / '+p.basis+' '+p.unit}${p.source?' · '+esc(p.source):''}</small></span><span>＋</span></button><button class="food-fav" aria-label="Toggle favorite" onclick="toggleFoodFavorite(${i})">${state.foodFavorites.includes(p.id)?'♥':'♡'}</button></div>`).join('')||'<div class="empty">Search for a product or enter its nutrition label.</div>'}</div><p class="small-muted"><a href="https://world.openfoodfacts.org" target="_blank" rel="noopener">Open Food Facts</a> · <a href="https://opendatacommons.org/licenses/odbl/1-0/" target="_blank" rel="noopener">ODbL</a> · Check values against your packaging.</p>`}
async function searchOnlineFood(){let q=foodPicker.q.trim();if(q.length<3){foodRemoteStatus='Enter at least 3 characters.';paintFoodResults();return}if(foodSearchCache.has(q)){remoteFoods=foodSearchCache.get(q);foodRemoteQuery=q;foodRemoteStatus='';paintFoodResults();return}if(Date.now()-lastFoodSearch<6500){foodRemoteStatus='Please wait a few seconds before searching again.';paintFoodResults();return}lastFoodSearch=Date.now();let seq=++foodRequest;foodRemoteStatus='Searching Open Food Facts…';paintFoodResults();try{let url='https://world.openfoodfacts.org/cgi/search.pl?search_simple=1&action=process&json=1&page_size=30&fields=code,product_name,product_name_en,brands,nutriments&search_terms='+encodeURIComponent(q);let data=await liveFetch(url);if(seq!==foodRequest)return;remoteFoods=(data.products||[]).map(normalizeOFF);foodRemoteQuery=q;foodSearchCache.set(q,remoteFoods);foodRemoteStatus=remoteFoods.length?'':'No online products found.'}catch{if(seq!==foodRequest)return;foodRemoteStatus='Food search unavailable. Try again or enter the label.'}paintFoodResults()}
function selectLiveFood(i){let p=displayedFoods[i];if(!p)return;if(p.incomplete){newLabelProduct(p.barcode);$('#label-name').value=p.name;$('#label-brand').value=p.brand;for(let [key,field] of [['cal','energy'],['p','p'],['c','c'],['f','f'],['sugar','sugar'],['saturates','saturates'],['fiber','fiber'],['salt','salt']])if(p[key]!==undefined)$('#label-'+field).value=p[key];toast('Complete the missing label values');return}portionModal(p)}
const originalFavorite=toggleFoodFavorite;
toggleFoodFavorite=function(i){if(typeof canUseForma==='function'&&!canUseForma())return;let p=displayedFoods[i];if(p?.source&&!state.products.some(x=>x.id===p.id))state.products.push(structuredClone(p));originalFavorite(i)};
lookupLocalBarcode=async function(event){event.preventDefault();let code=$('#barcode-value').value.trim();if(!/^\d{8,14}$/.test(code)){$('#barcode-status').textContent='Enter an 8–14 digit barcode.';return}let own=foodLibrary().find(x=>x.barcode===code);if(own){portionModal(own);return}let status=$('#barcode-status');status.textContent='Looking up product…';try{let data=await liveFetch('https://world.openfoodfacts.org/api/v3/product/'+code+'?fields=code,product_name,brands,nutriments');if(!status.isConnected)return;if(!data.product)throw Error('not found');let p=normalizeOFF(data.product);displayedFoods=[p];selectLiveFood(0)}catch{if(!status.isConnected)return;status.innerHTML='<p>Product unavailable or not found.</p><button type="button" class="text-btn" onclick="newLabelProduct(\''+code+'\')">Enter nutrition label</button>'}};
